#!/usr/bin/env python3
"""Render the frozen paired MOSS/procedural audio review and training surfaces."""
from pathlib import Path
import argparse,base64,copy,hashlib,html,json,sys
import numpy as np
from refresh_saved_caption import refresh_saved_caption
from training_formats import moss_training_formats
from humaneness_caption_settings import load_settings

PAGE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Procedural versus MOSS captions · The same 50 recordings</title><style>
:root{color-scheme:dark;--bg:#101522;--card:#192235;--line:#34415a;--ink:#edf3ff;--muted:#b2c0d8;--accent:#79dfdc;--violet:#b4a0ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.65 system-ui,sans-serif}main{max-width:1350px;margin:auto;padding:30px 24px 70px}a{color:var(--accent)}h1{font-size:clamp(30px,5vw,58px);line-height:1.1;letter-spacing:-.035em}h2{font-size:22px}h3{font-size:17px}.muted{color:var(--muted)}.eyebrow{color:var(--accent);font-size:12px;text-transform:uppercase;letter-spacing:.13em}.panel,article{border:1px solid var(--line);border-radius:16px;padding:22px;background:var(--card);margin:18px 0}.hero{background:linear-gradient(110deg,#203450,#292542)}.cols{display:grid;grid-template-columns:1fr 1fr;gap:22px}.cols>section{min-width:0}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px 11px;text-align:left;border-bottom:1px solid var(--line)}td.num{text-align:right;font-variant-numeric:tabular-nums}th{color:var(--muted)}audio{width:100%;height:42px}.caption,pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#111c2d;border-left:3px solid var(--accent);padding:14px;border-radius:5px;font-size:13px}.script{max-height:440px;overflow:auto}.event{padding:8px 0;border-bottom:1px solid var(--line);font-size:13px}.event button{color:var(--accent);font-variant-numeric:tabular-nums}button,select{background:#132036;color:var(--ink);border:1px solid var(--line);border-radius:7px;padding:7px;font:inherit}button{cursor:pointer}summary{cursor:pointer;font-weight:650}details{margin:14px 0}svg{width:100%;height:65px;background:#101b2d;border-radius:6px}nav{display:flex;gap:15px;flex-wrap:wrap}.review{color:var(--muted);font-size:13px}.pill{border:1px solid var(--line);border-radius:30px;padding:5px 12px;font-size:12px;display:inline-block;margin:3px}.hidden{display:none!important}code{color:var(--accent)}@media(max-width:800px){.cols{grid-template-columns:1fr}main{padding:18px 12px}.panel,article{padding:17px}}
</style></head><body><main><div class="eyebrow">LAION · Paired audio review · 11 October 2026</div><h1>Two captioning pipelines.<br>The same fifty recordings.</h1><nav><a href="https://laion-moss-voice-acting-captions.static.hf.space/">Bilingual MOSS listening room</a><a href="https://projects.laion.ai/procedural-voice-captions/humaneness-medium/">40 multilingual procedural examples</a><a href="https://github.com/LAION-AI/procedural-voice-captions/blob/main/PROMPT_FORMAT.md">Exact prompt grammar</a></nav>
<section class="panel hero"><h2>What was compared?</h2><p>The original 50 synthetic acting recordings (45 English, five German) were described by two pipelines: transparent rules applied to Humaneness Ears Medium scores, and the two MOSS captioning adapters. Both receive the same recordings. Neither receives the intended emotion, performance script or a reference caption.</p><p>Four procedural settings were compared on 25 recordings. The compact <code>guide-concise</code> setting was frozen before checking the remaining 25. The whole-audio MOSS caption and every selected interval caption were regenerated with greedy decoding and an uncapped 0.6 locator threshold. The original 90-clip demo used a three-event cap; this new comparison uses all selected events.</p><p><b>Result:</b> MOSS describes these recordings more faithfully under the shared review rubric. The compact procedural setting offers an auditable, reproducible surface but its generic event names and attribute wording receive lower fidelity scores. The compact and previous prose settings tie at 2.704/5 across all 50; this study does not establish a meaningful quality advantage for the shorter wording.</p></section>
<section class="panel"><h2>Same-audio results · 0–5 automated review scores</h2><p class="muted">Higher is better. Every recording has equal weight. “Precision” and “recall” below are the reviewer's ordinal 0–5 judgments, not measured statistical detection rates. Readability is reported separately and excluded from the composite.</p>__RESULT_TABLE__<p class="review">__INTERVALS__</p><h3>Confirmation set · 25 recordings not used to choose the setting</h3>__CONFIRM_TABLE__</section>
<section class="panel"><h2>Settings and interpretation</h2><div class="table"><table><thead><tr><th>Component</th><th>Frozen setting</th><th>Meaning</th></tr></thead><tbody><tr><td>Procedural locator</td><td>0.7 onset threshold; 0.08 s minimum; no event cap</td><td>Suppress intervals overlapping more than half the shorter interval. Retain every raw proposal.</td></tr><tr><td>Procedural wording</td><td>Two VoiceNet properties; up to one emotion at z ≥ +0.5; tempo always included; tags template</td><td>Normalize against 80,265 S10 + multilingual Emilia speech recordings. AudioBox Content Enjoyment supplies pleasantness wording.</td></tr><tr><td>MOSS locator</td><td>0.6; same minimum and overlap suppression; no cap</td><td>Its interval policy is documented separately from procedural captions. Different thresholds can yield different event counts.</td></tr><tr><td>MOSS decoding</td><td>Temperature 0 / greedy</td><td>The burst adapter gets the entire recording and both endpoints, without an event type label.</td></tr><tr><td>Prompt grammar</td><td><code>GENERAL:</code> and <code>SCRIPT:</code></td><td>Each speech segment has <code>[D seconds duration]</code>, each burst <code>(Label, D seconds)</code>, and each pause <code>[D seconds pause]</code>.</td></tr></tbody></table></div><p>Inline burst durations lie inside an inclusive speech-segment budget. They are descriptive durations and are <b>not added a second time</b> to elapsed time. A standalone burst advances the timeline. This documented extension preserves durations on events that overlap speech; the historical Humaneness Voice Small guide sometimes omitted their numbers. Exact start and end times remain in the JSON. Use the accompanying parser for the extended overlap semantics.</p><p>The repaired renderer passed the duration budget, word-order and selected-event count checks for <b>all 38,427 successfully generated English/German recordings</b>. This verifies formatting against saved model intervals; it does not verify whether those intervals correspond to genuine audible events.</p><details><summary>Reviewer, rubric, selection and limitations</summary><p>Actual reviewer version: <code>gemini-3.8-flash</code>. Candidate IDs and presentation order were blinded; prose style still reveals some pipeline differences. Each recording was reviewed once per phase with the same audio and rubric: caption fidelity 30%, burst-description fidelity 25%, timing 20%, event precision 15%, event recall 10%. There is no human reference annotation or inter-reviewer agreement estimate. The language-stratified split and selection rule were frozen before scores were requested.</p><p>The compact setting tied the longer tags setting on selection, so the shorter configuration was chosen. On confirmation, the previous prose setting scored 2.772 versus 2.760 for compact tags; this small difference does not establish an optimum. The 0.8 threshold lost event recall in selection. The historical 20-recording study and the old 50-recording MOSS event-cap study use different rubrics/protocols and must not be compared numerically to this shared test.</p><p>Bootstrap intervals resample paired recordings, retaining all options within each recording. They describe variation across this small synthetic listening set; they do not account for annotation error, reviewer bias, configuration selection or real-world domain shift.</p></details></section>
<section class="panel"><h2>Search over procedural settings</h2>__SEARCH_TABLE__<p class="muted">All candidates use the same measured reference, minimum duration, suppression rule and repaired timing grammar. Results are selection-set scores only; no retuning was performed using confirmation ratings.</p></section>
<h2 id="listen">Listen and inspect the training text</h2><p>All 50 players are embedded as original MP3 bytes in this HTML. Select a language, seek to an interval, and compare the complete procedural prompt with MOSS descriptions. Each card also provides the six <code>CAPTION / TRANSCRIPT</code> variants requested for downstream voice training.</p><label>Language <select id="language"><option value="">All</option><option value="en">English</option><option value="de">German</option></select></label> __CARDS__
<footer class="review">Machine-generated annotations, not human ground truth. New captions, code and evaluation metadata CC BY 4.0; upstream model licenses are retained. <a href="https://huggingface.co/laion/moss-voice-captioner">Whole-voice adapter</a> · <a href="https://huggingface.co/laion/moss-vocal-burst-captioner">Burst adapter</a> · <a href="https://huggingface.co/laion/humaneness-ears-base-medium">Humaneness Ears Medium</a>.</footer>
<script id="format-data" type="application/json">__VARIANTS__</script><script>
const variants=JSON.parse(document.getElementById('format-data').textContent);document.querySelectorAll('[data-format]').forEach(s=>s.addEventListener('change',()=>{document.getElementById('surface-'+s.dataset.format).textContent=variants[s.dataset.format][s.value].prompt}));document.querySelectorAll('[data-seek]').forEach(b=>b.addEventListener('click',()=>{const a=b.closest('article').querySelector('audio');a.currentTime=Number(b.dataset.seek);a.play()}));document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause()})));document.getElementById('language').addEventListener('change',e=>document.querySelectorAll('article[data-language]').forEach(c=>c.classList.toggle('hidden',e.target.value!==''&&c.dataset.language!==e.target.value)));
</script></main></body></html>'''


def table(rows,keys):
    return '<div class="table"><table><thead><tr>'+''.join('<th>'+html.escape(x[1])+'</th>' for x in keys)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td'+(' class="num"' if isinstance(row[k],(int,float)) else '')+'>'+ (f'{row[k]:.3f}' if isinstance(row[k],float) else html.escape(str(row[k])))+'</td>' for k,_ in keys)+'</tr>' for row in rows)+'</tbody></table></div>'


def render(args):
    root=args.input;baseline=json.loads((Path(__file__).parent/'baseline_stats_humaneness_medium_speech.json').read_text())
    manifest=[json.loads(x) for x in (root/'comparison_samples.jsonl').open()]
    refs={r['comparison_id']:r for r in map(json.loads,(root/'reference_samples.jsonl').open())}
    sample_events={r['id']:r['events'] for r in map(json.loads,(root/'samples.jsonl').open())}
    predictions={(r['sample_id'],r['task'],r['event_index']):r for p in root.glob('predictions-r*.jsonl') for r in map(json.loads,p.open())}
    ratings={r['id']:{x['config_id']:x for x in r['answer']['ratings']} for phase in ['selection','confirmation'] for p in root.glob(phase+'-*.json') if p.name!=phase+'-summary.json' for r in [json.loads(p.read_text())]}
    selection=json.loads((root/'selection-summary.json').read_text());confirmation=json.loads((root/'confirmation-summary.json').read_text())
    keys=[('name','Pipeline'),('weighted_score','Composite'),('caption_fidelity','Caption fidelity'),('burst_description_fidelity','Burst fidelity'),('timing_accuracy','Timing'),('event_precision','Event precision'),('event_recall','Event recall'),('readability','Readability')]
    titles={'guide-concise':'Procedural · compact tags','reviewed-prose':'Procedural · previous prose','moss':'MOSS · greedy, uncapped'}
    all_results=[]
    for config in titles:
        row={'name':titles[config],'config_id':config,'n':50}
        for k,_ in keys[1:]:row[k]=float(np.mean([r[config][k] for r in ratings.values()]))
        all_results.append(row)
    rng=np.random.default_rng(20261011)
    ci=[]
    for partition in ['all','confirmation']:
        ids=[r['id'] for r in manifest if partition=='all' or r['partition']==partition]
        delta=np.array([ratings[s]['moss']['weighted_score']-ratings[s]['guide-concise']['weighted_score'] for s in ids])
        b=delta[rng.integers(0,len(delta),size=(10000,len(delta)))].mean(1)
        ci.append({'partition':partition,'n':len(ids),'mean_moss_minus_procedural':float(delta.mean()),'paired_bootstrap_95_ci':np.quantile(b,[.025,.975]).tolist()})
    cards=[];variant_data={};proc_events=0;moss_events=0
    for sample in sorted(manifest,key=lambda x:(x['language']!='en',x['id'])):
        sid=sample['id'];options={o['config_id']:o for o in sample['options']};proc=options['guide-concise'];moss=options['moss']
        proc_events+=len(proc['events']);moss_events+=len(moss['events'])
        fresh=refresh_saved_caption(copy.deepcopy(refs[sid]),baseline,load_settings());assert fresh['procedural_caption']==proc['training_prompt']
        record={'voice_caption':{'prediction':moss['general_caption']},'audio_duration_s':sample['duration_s'],'locator_settings':{'threshold':.6,'min_duration_s':.08,'nms_overlap_fraction':.5,'event_cap':None},
                'burst_captions':[dict(e,caption={'prediction':predictions[(sid,'burst_caption',e['event_index'])]['prediction']}) for e in sample_events[sid]]}
        formats=moss_training_formats(fresh,record);variant_data[sid]=formats['variants']
        e=html.escape
        def events(option,color):
            rects=''.join(f'<rect x="{x["start_s"]/sample["duration_s"]*1000:.2f}" y="15" width="{max(1,(x["end_s"]-x["start_s"])/sample["duration_s"]*1000):.2f}" height="20" rx="3" fill="{color}"/>' for x in option['events'])
            timeline=f'<svg viewBox="0 0 1000 65" role="img" aria-label="Predicted vocal event intervals">{rects}<text x="5" y="57" fill="#b2c0d8" font-size="13">0 s</text><text x="900" y="57" fill="#b2c0d8" font-size="13">{sample["duration_s"]:.1f} s</text></svg>'
            return timeline+''.join(f'<div class="event"><button data-seek="{x["start_s"]}">{x["start_s"]:.2f}–{x["end_s"]:.2f} s</button> · {x["duration_s"]:.2f} s<br>{e(x["caption"])}</div>' for x in option['events'])
        selectors=''.join(f'<option value="{e(k)}">{e(k.replace("__"," / ").replace("_"," "))}</option>' for k in formats['variants'])
        blob=base64.b64encode(Path(sample['audio_path']).read_bytes()).decode()
        score=ratings[sid]
        cards.append(f'<article data-language="{sample["language"]}"><div class="eyebrow">{sample["language"].upper()} · {sample["partition"]} · {sample["duration_s"]:.1f} seconds</div><h2>{e(sid)}</h2><audio controls preload="none" src="data:audio/mpeg;base64,{blob}"></audio><div class="cols"><section><h3>Procedural · Humaneness Ears Medium</h3><p class="review">Shared composite {score["guide-concise"]["weighted_score"]:.2f}/5 · {len(proc["events"])} selected events</p><pre class="script">{e(proc["training_prompt"])}</pre>{events(proc,"#b4a0ff")}</section><section><h3>MOSS · whole voice + interval descriptions</h3><p class="review">Shared composite {score["moss"]["weighted_score"]:.2f}/5 · {len(moss["events"])} selected events</p><div class="caption">{e(moss["general_caption"])}</div>{events(moss,"#79dfdc")}</section></div><details><summary>Six CAPTION / TRANSCRIPT training choices</summary><p class="review">Whole-audio prose is unchanged; the “whole audio only” caption can itself mention a burst. The other caption appends chronological interval descriptions. Plain transcript is verbatim ASR; inline and timed variants use the MOSS-selected intervals.</p><select data-format="{e(sid)}">{selectors}</select><pre id="surface-{e(sid)}" class="script">{e(next(iter(formats["variants"].values()))["prompt"])}</pre></details><details><summary>Reviewer notes</summary><p>{e(score["guide-concise"]["note"])}</p><p>{e(score["moss"]["note"])}</p></details></article>')
    conf=[dict(confirmation['results'][k],name=titles[k]) for k in titles]
    search=[dict(selection['results'][k],name=k+' · '+next(c['template'] for c in json.loads((root/'configs.json').read_text()) if c['id']==k)) for k in selection['procedural_ranking']]
    intervals='; '.join(f'{c["partition"]}: MOSS minus compact procedural = {c["mean_moss_minus_procedural"]:.3f}, paired bootstrap 95% interval [{c["paired_bootstrap_95_ci"][0]:.3f}, {c["paired_bootstrap_95_ci"][1]:.3f}]' for c in ci)
    page=PAGE.replace('__RESULT_TABLE__',table(all_results,keys)).replace('__CONFIRM_TABLE__',table(conf,keys)).replace('__SEARCH_TABLE__',table(search,keys)).replace('__INTERVALS__',intervals).replace('__CARDS__',''.join(cards)).replace('__VARIANTS__',json.dumps(variant_data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
    args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(page)
    summary={'schema':'paired-caption-format-review-v1','n':50,'languages':{'en':45,'de':5},'selection_n':25,'confirmation_n':25,'results_all50':all_results,'confirmation':confirmation,'selection':selection,'bootstrap':ci,'selected_config':'guide-concise','selected_before_confirmation':True,'moss_events':moss_events,'procedural_events':proc_events,'all_50_timed_formats_verified':True,'training_variants_per_clip':6,'model_version':'gemini-3.8-flash','corpus_format_check':json.loads((root/'CORPUS_FORMAT_CHECK.json').read_text()),'automated_review_not_human_ground_truth':True,'rubric':selection['rubric']}
    args.summary.write_text(json.dumps(summary,indent=2)+'\n')
    assert page.count('data:audio/mpeg;base64,')==50
    print('PAIRED_FORMAT_REPORT_READY',len(cards),args.output.stat().st_size)


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--summary',type=Path,required=True);render(p.parse_args())
